from PIL import Image
import glob, os, subprocess

files = sorted(glob.glob('/home/ctfplayer/workspace/frames200/g_*.png'))
os.makedirs('/home/ctfplayer/workspace/ocr_crops', exist_ok=True)

def prep(mask, y0, y1, x0, x1, name, scale=5):
    sub = mask[y0:y1, x0:x1]
    if sub.sum() < 10:
        return None
    img = np.full(sub.shape, 255, dtype=np.uint8)
    img[sub] = 0
    im = Image.fromarray(img).resize((sub.shape[1] * scale, sub.shape[0] * scale), Image.LANCZOS)
    p = f'/home/ctfplayer/workspace/ocr_crops/{name}.png'
    im.save(p)
    return p

results = {}
for i, f in enumerate(files):
    a = np.asarray(Image.open(f).convert('RGB'), dtype=np.int16)
    mx = a.max(axis=2)
    m = (mx < 10)
    # block1 region and block2 region
    for bi, (yy0, yy1, xx0, xx1) in enumerate([(0, 190, 820, 1080), (130, 320, 980, 1220)]):
        sub = m[yy0:yy1, xx0:xx1]
        if sub.sum() < 15:
            continue
        p = prep(m, yy0, yy1, xx0, xx1, f'b{bi}_f{i+195}')
        if p:
            try:
                out = subprocess.run(['tesseract', p, 'stdout', '--psm', '7'],
                                     capture_output=True, text=True, timeout=30)
                txt = out.stdout.strip().replace('\n', ' | ')
            except Exception as e:
                txt = f'ERR {e}'
            results.setdefault(bi, []).append((i + 195, int(sub.sum()), txt))

for bi, lst in results.items():
    print(f'===== block {bi} =====')
    for fr, cnt, txt in lst:
        print(fr, cnt, repr(txt))
